package com.beyondsignal.game.event; import static org.junit.jupiter.api.Assertions.*; import com.beyondsignal.game.galaxy.*; import java.util.*; import org.junit.jupiter.api.Test; class ExplorationEventGeneratorTest{ @Test void sameInputsProduceSameEvent(){ StarSystem s=new StarSystem("vega","Vega",new Coordinates(1,2,3),"A",List.of(),false,false,false,false); var g=new ExplorationEventGenerator(); var a=g.generate(s,100,42); var b=g.generate(s,100,42); assertEquals(a,b); assertEquals(ExplorationEventStatus.PENDING,a.status()); assertFalse(a.choices().isEmpty()); }}
